css:
.bank-advice { font-size: 12px; color: #000; }
.advice-head .company { margin: 0 0 2px 0; font-size: 18px; }
.advice-head .title { font-size: 13px; }
.advice-head { margin-bottom: 12px; }
.advice-table, .summary-table { width: 100%; border-collapse: collapse; }
.advice-table th, .advice-table td { padding: 4px 6px; vertical-align: top; }
.advice-table thead th { border-top: 1px solid #000; border-bottom: 1px solid #000; text-align: left; white-space: nowrap; }
.advice-table tbody td { border-bottom: 0; }
.advice-table tr.grand-total td { border-top: 1px solid #000; border-bottom: 1px solid #000; }
.summary-block { margin-top: 28px; }
.summary-block h4 { margin: 0 0 6px 0; font-size: 13px; }
.summary-table { max-width: 460px; }
.summary-table th, .summary-table td { padding: 4px 8px; }
.summary-table thead th { border-bottom: 1px solid #000; text-align: left; }
.summary-table tr.grand-total td { border-top: 1px solid #000; }
.advice-footer { margin-top: 45px; }
.advice-footer .sign-line { margin-bottom: 18px; }
.text-right { text-align: right; }
.text-center { text-align: center; }

/* Full grid borders on both tables */
.advice-table thead th, .advice-table tbody td,
.summary-table thead th, .summary-table tbody td { border: 1px solid #000; }

/* Align the headers with their data cells */
.advice-table thead th.text-right,
.summary-table thead th.text-right { text-align: right; }
.advice-table thead th.text-center,
.summary-table thead th.text-center { text-align: center; }
